import { Download, NotebookPen, Settings, LogOut, User, Search, X, Smartphone } from "lucide-react";
import { useEffect, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import * as api from "@/lib/api";
import { ApiError } from "@/lib/api-error";
import { toast } from "sonner";

const ARGON2_TOAST =
  "This account uses a legacy Argon2 password. In the worker folder run: node scripts/d1-set-password-sha256.mjs USERNAME NEW_PASSWORD, then run the printed wrangler d1 execute command, and sign in with the new password.";

function toastAuthError(err: unknown, fallback: string) {
  if (err instanceof ApiError) {
    const m = err.message.trim();
    toast.error(m === "argon2_unavailable" ? ARGON2_TOAST : err.message);
    return;
  }
  toast.error(fallback);
}

interface HeaderProps {
  onImportKeep: () => void;
  isImportingKeep: boolean;
  searchQuery?: string;
  onSearchChange?: (query: string) => void;
}

export function Header({
  onImportKeep,
  isImportingKeep,
  searchQuery,
  onSearchChange,
}: HeaderProps) {
  const queryClient = useQueryClient();
  const [loginOpen, setLoginOpen] = useState(false);
  const [authTab, setAuthTab] = useState<"login" | "register">("login");
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const [loginUser, setLoginUser] = useState("");
  const [loginPass, setLoginPass] = useState("");
  const [regEmail, setRegEmail] = useState("");
  const [installPrompt, setInstallPrompt] = useState<BeforeInstallPromptEvent | null>(null);

  useEffect(() => {
    const handler = (e: BeforeInstallPromptEvent) => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener("beforeinstallprompt", handler as EventListener);
    return () => window.removeEventListener("beforeinstallprompt", handler as EventListener);
  }, []);

  const isStandalone =
    typeof window !== "undefined" && window.matchMedia("(display-mode: standalone)").matches;

  const meQuery = useQuery({
    queryKey: ["auth", "me"],
    queryFn: api.fetchAuthMe,
    staleTime: 60_000,
    retry: false,
  });

  const loginMut = useMutation({
    mutationFn: () => api.login(loginUser.trim(), loginPass),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["auth", "me"] });
      queryClient.invalidateQueries({ queryKey: ["notes"] });
      setLoginOpen(false);
      setLoginPass("");
      toast.success("Signed in");
    },
    onError: (err) => toastAuthError(err, "Sign-in failed"),
  });

  const registerMut = useMutation({
    mutationFn: () =>
      api.register({
        username: loginUser.trim(),
        email: regEmail.trim(),
        password: loginPass,
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["auth", "me"] });
      queryClient.invalidateQueries({ queryKey: ["notes"] });
      setLoginOpen(false);
      setLoginPass("");
      setRegEmail("");
      toast.success("Registered and signed in");
    },
    onError: (err) => toastAuthError(err, "Registration failed"),
  });

  const logoutMut = useMutation({
    mutationFn: api.logout,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["auth", "me"] });
      queryClient.invalidateQueries({ queryKey: ["notes"] });
      toast.success("Signed out");
    },
  });

  const me = meQuery.data;
  const displayName = me?.username ?? "Not signed in";
  const displayEmail = me?.email ?? "Account details appear after sign-in";
  const initial = me?.username?.trim().charAt(0).toUpperCase() ?? "?";

  return (
    <header className="sticky top-0 z-40 glass-effect border-b border-border/30">
      <div className="container mx-auto px-6 h-20 relative flex items-center justify-between gap-3 sm:gap-4">
        <div className="absolute left-1/2 top-1/2 hidden -translate-x-1/2 -translate-y-1/2 md:block pointer-events-none">
          <div
            className={`
              relative w-[min(42rem,calc(100%-20rem))] pointer-events-auto flex items-center rounded-2xl border transition-all duration-300
              ${isSearchFocused ? "bg-card shadow-note-hover border-border" : "bg-secondary/60 border-transparent hover:bg-secondary/80"}
            `}
          >
            <Search
              className={`absolute left-4 w-4 h-4 transition-colors duration-200 ${isSearchFocused ? "text-primary" : "text-muted-foreground"}`}
            />
            <input
              type="text"
              value={searchQuery ?? ""}
              onChange={(e) => onSearchChange?.(e.target.value)}
              onFocus={() => setIsSearchFocused(true)}
              onBlur={() => setIsSearchFocused(false)}
              placeholder="Search notes..."
              className="w-full py-2.5 pl-11 pr-10 bg-transparent text-sm text-foreground placeholder:text-muted-foreground focus:outline-none"
            />
            {(searchQuery ?? "").length > 0 && (
              <button
                onClick={() => onSearchChange?.("")}
                className="absolute right-3 p-1 rounded-lg hover:bg-foreground/8 transition-colors"
                title="Clear"
              >
                <X className="w-4 h-4 text-muted-foreground" />
              </button>
            )}
          </div>
        </div>

        <div className="flex items-center gap-4 cursor-pointer">
          <div className="relative">
            <div className="absolute inset-0 bg-primary/20 rounded-2xl blur-xl" />
            <div className="relative w-12 h-12 rounded-2xl bg-gradient-to-br from-primary to-accent flex items-center justify-center shadow-lg">
              <NotebookPen className="w-6 h-6 text-primary-foreground" />
            </div>
          </div>
          <div>
            <h1 className="text-2xl font-display text-foreground tracking-tight">Zenotes</h1>
            <p className="text-xs text-muted-foreground">Quiet space for ideas</p>
          </div>
        </div>

        <div className="flex items-center gap-3 sm:gap-4">
          {installPrompt && !isStandalone && (
            <Button
              variant="outline"
              size="sm"
              onClick={async () => {
                await installPrompt.prompt();
                const { outcome } = await installPrompt.userChoice;
                if (outcome === "accepted") setInstallPrompt(null);
              }}
              className="hidden sm:flex items-center gap-2"
            >
              <Smartphone className="h-4 w-4" />
              Install
            </Button>
          )}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-primary/20 to-accent/20 flex items-center justify-center cursor-pointer border border-primary/10 hover:border-primary/30 hover:shadow-sm transition-all outline-none">
                <span className="text-sm font-medium text-primary-foreground text-gradient">{initial}</span>
              </div>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-56">
              <DropdownMenuLabel className="font-normal">
                <div className="flex flex-col space-y-1">
                  <p className="text-sm font-medium leading-none">{displayName}</p>
                  <p className="text-xs leading-none text-muted-foreground break-all">{displayEmail}</p>
                </div>
              </DropdownMenuLabel>
              <DropdownMenuSeparator />
              {!me && (
                <DropdownMenuItem
                  className="cursor-pointer"
                  onClick={(e) => {
                    e.preventDefault();
                    setAuthTab("login");
                    setLoginOpen(true);
                  }}
                >
                  <User className="mr-2 h-4 w-4" />
                  <span>Sign in</span>
                </DropdownMenuItem>
              )}
              <DropdownMenuItem className="cursor-pointer" disabled>
                <User className="mr-2 h-4 w-4" />
                <span>Profile</span>
              </DropdownMenuItem>
              <DropdownMenuItem className="cursor-pointer" disabled>
                <Settings className="mr-2 h-4 w-4" />
                <span>Settings</span>
              </DropdownMenuItem>
              <DropdownMenuItem
                className="cursor-pointer"
                disabled={isImportingKeep || !me}
                onClick={(e) => {
                  e.preventDefault();
                  if (me) onImportKeep();
                }}
              >
                {isImportingKeep ? (
                  <>
                    <span className="mr-2 h-4 w-4 rounded-full border-2 border-foreground/30 border-t-foreground animate-spin" />
                    <span>Importing…</span>
                  </>
                ) : (
                  <>
                    <Download className="mr-2 h-4 w-4" />
                    <span>Import Google Keep</span>
                  </>
                )}
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                className="cursor-pointer text-destructive focus:text-destructive"
                onClick={(e) => {
                  e.preventDefault();
                  logoutMut.mutate();
                }}
              >
                <LogOut className="mr-2 h-4 w-4" />
                <span>Sign out</span>
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      <Dialog
        open={loginOpen}
        onOpenChange={(open) => {
          setLoginOpen(open);
          if (!open) {
            setAuthTab("login");
            setLoginPass("");
            setRegEmail("");
          }
        }}
      >
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{authTab === "login" ? "Sign in" : "Register"}</DialogTitle>
          </DialogHeader>
          <div className="flex gap-2 border-b border-border pb-2">
            <Button
              type="button"
              variant={authTab === "login" ? "secondary" : "ghost"}
              size="sm"
              className="flex-1"
              onClick={() => setAuthTab("login")}
            >
              Sign in
            </Button>
            <Button
              type="button"
              variant={authTab === "register" ? "secondary" : "ghost"}
              size="sm"
              className="flex-1"
              onClick={() => setAuthTab("register")}
            >
              Register
            </Button>
          </div>
          <div className="grid gap-4 py-2">
            <div className="grid gap-2">
              <Label htmlFor="login-username">Username</Label>
              <Input
                id="login-username"
                autoComplete="username"
                value={loginUser}
                onChange={(e) => setLoginUser(e.target.value)}
              />
            </div>
            {authTab === "register" && (
              <div className="grid gap-2">
                <Label htmlFor="reg-email">Email</Label>
                <Input
                  id="reg-email"
                  type="email"
                  autoComplete="email"
                  value={regEmail}
                  onChange={(e) => setRegEmail(e.target.value)}
                />
              </div>
            )}
            <div className="grid gap-2">
              <Label htmlFor="login-password">Password</Label>
              <Input
                id="login-password"
                type="password"
                autoComplete={authTab === "login" ? "current-password" : "new-password"}
                value={loginPass}
                onChange={(e) => setLoginPass(e.target.value)}
              />
            </div>
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => setLoginOpen(false)}>
              Cancel
            </Button>
            {authTab === "login" ? (
              <Button
                type="button"
                disabled={loginMut.isPending || !loginUser.trim() || !loginPass}
                onClick={() => loginMut.mutate()}
              >
                {loginMut.isPending ? "Signing in…" : "Sign in"}
              </Button>
            ) : (
              <Button
                type="button"
                disabled={
                  registerMut.isPending ||
                  !loginUser.trim() ||
                  !loginPass ||
                  !regEmail.includes("@")
                }
                onClick={() => registerMut.mutate()}
              >
                {registerMut.isPending ? "Submitting…" : "Register"}
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </header>
  );
}

import type { Note } from "@/types/note";
import * as api from "@/lib/api";
import { db } from "./db";
import { processSyncQueue } from "./syncEngine";

/** Merge server notes into IndexedDB without resurrecting locally deleted tombstones. */
export async function mergeServerNotesIntoLocal(notes: Note[]) {
  const pendingCreates = new Set(
    (await db.syncQueue.where("type").equals("CREATE_NOTE").toArray()).map((op) => op.entityId),
  );

  await db.transaction("rw", db.notes, async () => {
    for (const note of notes) {
      if (pendingCreates.has(note.id)) continue;

      const exists = await db.notes.get(note.id);
      if (exists?.isDeleted) continue;
      if (exists) {
        if (exists.syncStatus === "synced") {
          await db.notes.update(note.id, {
            ...note,
            title: note.title ?? null,
            tags: note.tags ?? [],
            syncStatus: "synced",
            isDeleted: false,
          } as any);
        }
        continue;
      }

      try {
        await db.notes.add({
          ...note,
          title: note.title ?? null,
          tags: note.tags ?? [],
          syncStatus: "synced",
          isDeleted: false,
        } as any);
      } catch (err) {
        // Race: another tab or sync just wrote this id — update instead of crashing.
        if (err instanceof Error && err.name === "ConstraintError") {
          await db.notes.update(note.id, {
            ...note,
            title: note.title ?? null,
            tags: note.tags ?? [],
            syncStatus: "synced",
            isDeleted: false,
          } as any);
        } else {
          throw err;
        }
      }
    }

    // Purge local synced notes that no longer exist on the server (e.g. wiped/deleted on server)
    const serverIds = new Set(notes.map((n) => n.id));
    const allLocal = await db.notes.filter((n) => !n.isDeleted && n.syncStatus === "synced").toArray();
    for (const local of allLocal) {
      if (!serverIds.has(local.id) && !pendingCreates.has(local.id)) {
        await db.notes.delete(local.id);
      }
    }
  });
}

/** Push local changes first, then merge server state (avoids seed/sync races). */
export async function pullServerNotes() {
  await processSyncQueue();
  const data = await api.fetchNotes(1, 1000);
  await mergeServerNotesIntoLocal(data.notes);
  return data;
}

import { db } from "./db";
import * as api from "../lib/api";
import { ApiError } from "../lib/api-error";
import { getPendingImagesForNote, markImageSynced, replaceLocalImageUrls } from "./imageCache";
import { markNoteSynced, tombstoneNote } from "./localNoteApi";

const MAX_RETRIES = 3;
const SYNC_LOCK_NAME = "zenotes-sync";

let _syncing = false;

export async function processSyncQueue() {
  const run = async () => {
    if (_syncing) return;
    _syncing = true;
    try {
      await processSyncQueueInner();
    } finally {
      _syncing = false;
    }
  };

  if (typeof navigator !== "undefined" && "locks" in navigator) {
    await navigator.locks.request(SYNC_LOCK_NAME, run);
  } else {
    await run();
  }
}

async function claimCreateNote(entityId: string): Promise<boolean> {
  return db.transaction("rw", db.notes, async () => {
    const note = await db.notes.get(entityId);
    if (!note || note.isDeleted) return false;
    if (note.syncStatus === "synced" || note.syncStatus === "syncing") return false;
    await db.notes.update(entityId, { syncStatus: "syncing" });
    return true;
  });
}

async function processSyncQueueInner() {
  try {
    const user = await api.fetchAuthMe();
    if (!user) return;
  } catch {
    return;
  }

  // Recover from a crash mid-sync (note left as "syncing").
  await db.notes.where("syncStatus").equals("syncing").modify({ syncStatus: "pending" });

  while (true) {
    const pending = await db.syncQueue.orderBy("createdAt").toArray();
    if (pending.length === 0) break;

    let processed = 0;
    for (const op of pending) {
      if (!op.id) continue;

      if (op.retries >= MAX_RETRIES) {
        await db.syncQueue.delete(op.id);
        processed++;
        continue;
      }

      if (op.type === "CREATE_NOTE") {
        const localNote = await db.notes.get(op.entityId);
        if (!localNote || localNote.isDeleted) {
          await db.syncQueue.delete(op.id);
          processed++;
          continue;
        }
        if (localNote.syncStatus === "synced") {
          await db.syncQueue.delete(op.id);
          processed++;
          continue;
        }
        if (localNote.syncStatus === "syncing") {
          continue;
        }
      }

      try {
        const completed = await executeOperation(op);
        if (!completed) continue;
        await db.syncQueue.delete(op.id);
        processed++;
      } catch (err) {
        const msg = err instanceof ApiError ? err.message : (err instanceof Error ? err.message : String(err));
        console.error("[SyncEngine] failed", op.type, op.entityId, msg);
        if (op.type === "CREATE_NOTE") {
          const note = await db.notes.get(op.entityId);
          if (note?.syncStatus === "syncing") {
            await db.notes.update(op.entityId, { syncStatus: "pending" });
          }
        }
        await db.syncQueue.update(op.id, { retries: op.retries + 1 });
      }
    }

    if (processed === 0) break;
  }
}

async function executeOperation(op: { type: string; entityId: string; payload: Record<string, unknown> }): Promise<boolean> {
  switch (op.type) {
    case "CREATE_NOTE": {
      const claimed = await claimCreateNote(op.entityId);
      if (!claimed) return false;

      const p = op.payload ?? {};
      const createBody: Record<string, unknown> = { id: op.entityId };
      if (typeof p.content === "string") createBody.content = p.content;
      if (typeof p.title === "string" && p.title) createBody.title = p.title;
      if (typeof p.color === "string") createBody.color = p.color;
      if (Array.isArray(p.tags)) createBody.tags = p.tags;

      try {
        const serverNote = await api.createNote(createBody as any);
        await markNoteSynced(op.entityId, serverNote as any);
        const finalId = serverNote?.id || op.entityId;
        await syncImagesForNote(finalId);
      } catch (err) {
        const note = await db.notes.get(op.entityId);
        if (note?.syncStatus === "syncing") {
          await db.notes.update(op.entityId, { syncStatus: "pending" });
        }
        throw err;
      }
      break;
    }
    case "UPDATE_NOTE": {
      const p = op.payload ?? {};
      const updateBody: Record<string, unknown> = {};
      if (typeof p.content === "string") updateBody.content = p.content;
      if (p.title !== undefined) updateBody.title = typeof p.title === "string" ? p.title : null;
      if (typeof p.color === "string") updateBody.color = p.color;
      if (Array.isArray(p.tags)) updateBody.tags = p.tags;
      if (typeof p.pinned === "boolean") updateBody.pinned = p.pinned;

      await api.updateNote(op.entityId, updateBody as any);
      await markNoteSynced(op.entityId);
      await syncImagesForNote(op.entityId);
      break;
    }
    case "DELETE_NOTE": {
      await api.deleteNote(op.entityId);
      await tombstoneNote(op.entityId);
      break;
    }
    case "UPLOAD_IMAGE": {
      break;
    }
    default:
      console.warn("[SyncEngine] unknown op", op);
  }
  return true;
}

async function syncImagesForNote(noteId: string) {
  const images = await getPendingImagesForNote(noteId);
  if (images.length === 0) return;
  const note = await db.notes.get(noteId);
  if (!note) return;

  const urlMap: Record<string, string> = {};
  for (const image of images) {
    const file = new File([image.blob], `${image.id}.png`, { type: image.mimeType });
    const result = (await api.uploadImage(noteId, file)) as { imageUrl: string };
    urlMap[image.id] = result.imageUrl;
    await markImageSynced(image.id);
  }

  if (Object.keys(urlMap).length > 0) {
    const newContent = replaceLocalImageUrls(note.content, urlMap);
    await db.notes.update(noteId, { content: newContent, syncStatus: "pending", updatedAt: new Date().toISOString() });
    await db.syncQueue.add({
      type: "UPDATE_NOTE",
      entityId: noteId,
      payload: { content: newContent },
      retries: 0,
      createdAt: Date.now(),
    });
  }
}

import React, { createContext, useContext, useMemo, useCallback, useState, useEffect } from "react";
import type { Note, NoteColor } from "@/types/note";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { liveQuery } from "dexie";

import * as api from "@/lib/api";
import { ApiError } from "@/lib/api-error";
import { useNetworkStatus } from "@/offline/network";
import { requestSync } from "@/offline/syncScheduler";
import {
  createLocalNote,
  updateLocalNote,
  deleteLocalNote,
  getLocalNotes,
  getLocalNote,
  type NoteInput,
} from "@/offline/localNoteApi";
import { db } from "@/offline/db";
import { pullServerNotes } from "@/offline/notesSeed";

const PINNED_CONTAINER_ID = "pinned";
const UNPINNED_CONTAINER_ID = "unpinned";
const PAGE_SIZE = 50;

function sortPosition(n: Note): number {
  return Number.isFinite(n.position) ? n.position : 0;
}

function computeMove(
  notes: Note[],
  activeId: string,
  overId: string,
  destPinned: boolean,
): {
  nextNotes: Note[];
  pinnedIds: string[];
  unpinnedIds: string[];
  pinnedChanged: boolean;
} {
  const pinnedNotes = notes.filter((n) => n.pinned).sort((a, b) => sortPosition(a) - sortPosition(b));
  const unpinnedNotes = notes.filter((n) => !n.pinned).sort((a, b) => sortPosition(a) - sortPosition(b));

  const active = notes.find((n) => n.id === activeId);
  if (!active) {
    return {
      nextNotes: notes,
      pinnedIds: pinnedNotes.map((n) => n.id),
      unpinnedIds: unpinnedNotes.map((n) => n.id),
      pinnedChanged: false,
    };
  }

  const sourcePinned = active.pinned;
  const pinnedChanged = sourcePinned !== destPinned;

  const srcArr = sourcePinned ? pinnedNotes : unpinnedNotes;
  const dstArr = destPinned ? pinnedNotes : unpinnedNotes;

  const srcWithout = srcArr.filter((n) => n.id !== activeId);
  const dstWithout = destPinned === sourcePinned ? srcWithout : dstArr;

  const insertIndex =
    overId === PINNED_CONTAINER_ID || overId === UNPINNED_CONTAINER_ID
      ? dstWithout.length
      : Math.max(
          0,
          dstWithout.findIndex((n) => n.id === overId),
        );

  const moved: Note = { ...active, pinned: destPinned };

  const dstNext = [...dstWithout.slice(0, insertIndex), moved, ...dstWithout.slice(insertIndex)];

  const nextPinned = (destPinned ? dstNext : srcWithout)
    .map((n, idx) => ({ ...n, pinned: true, position: idx + 1 }));
  const nextUnpinned = (!destPinned ? dstNext : srcWithout)
    .map((n, idx) => ({ ...n, pinned: false, position: idx + 1 }));

  return {
    nextNotes: [...nextPinned, ...nextUnpinned],
    pinnedIds: nextPinned.map((n) => n.id),
    unpinnedIds: nextUnpinned.map((n) => n.id),
    pinnedChanged,
  };
}

function useNotesService() {
  const queryClient = useQueryClient();
  const { isOnline } = useNetworkStatus();
  const [page, setPage] = useState(1);
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedTag, setSelectedTag] = useState<string | null>(null);

  // Seed local DB from server on mount / when online
  const seedQuery = useQuery({
    queryKey: ["notes", "seed"],
    queryFn: async () => {
      try {
        return await pullServerNotes();
      } catch (err) {
        console.error("[notes seed]", err);
        return {
          notes: [],
          pagination: { page: 1, pageSize: 1000, total: 0, totalPages: 0 },
        };
      }
    },
    enabled: isOnline,
    staleTime: 5 * 60 * 1000,
  });

  // Live local notes
  const [localNotes, setLocalNotes] = useState<Note[]>([]);
  useEffect(() => {
    const subscription = liveQuery(() => getLocalNotes()).subscribe(
      (notes) => setLocalNotes(notes as Note[]),
      (err) => console.error("[notes liveQuery]", err),
    );
    return () => subscription.unsubscribe();
  }, []);

  const allNotes = useMemo(() => {
    return [...localNotes].sort((a, b) => {
      if (Boolean(a.pinned) !== Boolean(b.pinned)) {
        return a.pinned ? -1 : 1;
      }
      const posA = sortPosition(a);
      const posB = sortPosition(b);
      if (posA !== posB) {
        return posA - posB;
      }
      return b.updatedAt.localeCompare(a.updatedAt);
    });
  }, [localNotes]);

  const searchedNotes = useMemo(() => {
    if (!searchQuery.trim()) return allNotes;
    const lowerQuery = searchQuery.toLowerCase();
    return allNotes.filter(
      (note) =>
        (note.content ?? "").toLowerCase().includes(lowerQuery) ||
        note.title?.toLowerCase().includes(lowerQuery) ||
        (note.tags ?? []).some((t) => t.toLowerCase().includes(lowerQuery)),
    );
  }, [allNotes, searchQuery]);

  const filteredNotes = useMemo(() => {
    if (!selectedTag) return searchedNotes;
    return searchedNotes.filter((n) => n.tags?.includes(selectedTag));
  }, [searchedNotes, selectedTag]);

  const allTags = useMemo(() => {
    const set = new Set<string>();
    allNotes.forEach((n) => n.tags?.forEach((t) => set.add(t)));
    return Array.from(set).sort((a, b) => a.localeCompare(b));
  }, [allNotes]);

  const total = filteredNotes.length;
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);
  const start = (safePage - 1) * PAGE_SIZE;
  const paginatedNotes = useMemo(
    () => filteredNotes.slice(start, start + PAGE_SIZE),
    [filteredNotes, start],
  );

  const pinnedNotes = useMemo(
    () =>
      paginatedNotes
        .filter((n) => n.pinned)
        .sort((a, b) => {
          const posDiff = sortPosition(a) - sortPosition(b);
          if (posDiff !== 0) return posDiff;
          return b.updatedAt.localeCompare(a.updatedAt);
        }),
    [paginatedNotes],
  );
  const unpinnedNotes = useMemo(
    () =>
      paginatedNotes
        .filter((n) => !n.pinned)
        .sort((a, b) => {
          const posDiff = sortPosition(a) - sortPosition(b);
          if (posDiff !== 0) return posDiff;
          return b.updatedAt.localeCompare(a.updatedAt);
        }),
    [paginatedNotes],
  );

  const addNoteMutation = useMutation({
    mutationFn: (input: { content: string; title?: string; color?: NoteColor; tags?: string[] }) =>
      createLocalNote(input as NoteInput),
    networkMode: "always",
    onSuccess: () => {
      setPage(1);
      queryClient.invalidateQueries({ queryKey: ["notes"] });
      if (isOnline) requestSync();
    },
    onError: (err) => {
      const msg = err instanceof ApiError ? err.message : "保存失败，请稍后重试";
      toast.error(msg);
    },
  });

  const updateNoteMutation = useMutation({
    mutationFn: ({ id, updates }: { id: string; updates: Partial<Note> }) =>
      updateLocalNote(id, updates as NoteInput),
    networkMode: "always",
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["notes"] });
      if (isOnline) requestSync();
    },
    onError: (err) => {
      const msg = err instanceof ApiError ? err.message : "更新失败，请稍后重试";
      toast.error(msg);
    },
  });

  const deleteNoteMutation = useMutation({
    mutationFn: (id: string) => deleteLocalNote(id),
    networkMode: "always",
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["notes"] });
      toast.success("Note deleted");
      if (isOnline) requestSync();
    },
    onError: (err) => {
      const msg = err instanceof ApiError ? err.message : "删除失败，请稍后重试";
      toast.error(msg);
    },
  });

  const moveMutation = useMutation({
    networkMode: "always",
    mutationFn: async (vars: {
      activeId: string;
      overId: string;
      destPinned: boolean;
      pinnedIds: string[];
      unpinnedIds: string[];
      pinnedChanged: boolean;
      nextNotes: Note[];
    }) => {
      // Update local positions/pinned first
      await db.transaction("rw", db.notes, async () => {
        for (const n of vars.nextNotes) {
          await db.notes.update(n.id, { pinned: n.pinned, position: n.position });
        }
      });
      // Sync to server when online
      if (vars.pinnedChanged) {
        await updateLocalNote(vars.activeId, { pinned: vars.destPinned });
      }
      await Promise.all([
        api.reorderNotes(true, vars.pinnedIds),
        api.reorderNotes(false, vars.unpinnedIds),
      ]);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["notes"] });
      if (isOnline) requestSync();
    },
    onError: (err) => {
      const msg = err instanceof ApiError ? err.message : "Reorder failed";
      toast.error(msg);
    },
  });

  const importGoogleKeepMutation = useMutation({
    mutationFn: (files: { raw: string }[]) => api.importGoogleKeep(files),
    networkMode: "always",
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["notes"] });
      // Force re-seed from server
      queryClient.invalidateQueries({ queryKey: ["notes", "seed"] });
    },
  });

  const addNote = useCallback(
    (content: string, title?: string, color: NoteColor = "white", tags: string[] = []) => {
      if (addNoteMutation.isPending) return;
      addNoteMutation.mutate({ content, title, color, tags });
    },
    [addNoteMutation],
  );

  const addNoteAsync = useCallback(
    async (content: string, title?: string, color: NoteColor = "white", tags: string[] = []) => {
      return addNoteMutation.mutateAsync({ content, title, color, tags });
    },
    [addNoteMutation],
  );

  const updateNote = useCallback(
    (id: string, updates: Partial<Omit<Note, "id">>) => {
      updateNoteMutation.mutate({ id, updates });
    },
    [updateNoteMutation],
  );

  const deleteNote = useCallback((id: string) => deleteNoteMutation.mutate(id), [deleteNoteMutation]);

  const togglePin = useCallback(
    (id: string) => {
      const note = allNotes.find((n) => n.id === id);
      if (!note) return;
      updateNoteMutation.mutate({ id, updates: { pinned: !note.pinned } });
    },
    [allNotes, updateNoteMutation],
  );

  const moveNote = useCallback(
    (activeId: string, overId: string, destPinned: boolean) => {
      const computed = computeMove(allNotes, activeId, overId, destPinned);
      moveMutation.mutate({ activeId, overId, destPinned, ...computed });
    },
    [allNotes, moveMutation],
  );

  const importGoogleKeep = useCallback(
    (files: { raw: string }[]) => importGoogleKeepMutation.mutateAsync(files),
    [importGoogleKeepMutation],
  );

  const searchNotes = useCallback(
    (query: string) => {
      if (!query.trim()) return allNotes;
      const lowerQuery = query.toLowerCase();
      return allNotes.filter(
        (note) =>
          (note.content ?? "").toLowerCase().includes(lowerQuery) ||
          note.title?.toLowerCase().includes(lowerQuery) ||
          (note.tags ?? []).some((t) => t.toLowerCase().includes(lowerQuery)),
      );
    },
    [allNotes],
  );

  return {
    notes: paginatedNotes,
    pinnedNotes,
    unpinnedNotes,
    addNote,
    addNoteAsync,
    updateNote,
    deleteNote,
    togglePin,
    moveNote,
    importGoogleKeep,
    searchNotes,
    isImportingKeep: importGoogleKeepMutation.isPending,
    isAddingNote: addNoteMutation.isPending,
    isLoading: seedQuery.isLoading,
    isError: seedQuery.isError,
    pagination: {
      page: safePage,
      pageSize: PAGE_SIZE,
      total,
      totalPages,
    },
    page: safePage,
    setPage,
    pageSize: PAGE_SIZE,
    setPageSize: () => {}, // no-op; page size fixed for simplicity
    searchQuery,
    setSearchQuery,
    selectedTag,
    setSelectedTag,
    allTags,
  };
}

type NotesContextType = ReturnType<typeof useNotesService>;
const NotesContext = createContext<NotesContextType | null>(null);

export function NotesProvider({ children }: { children: React.ReactNode }) {
  const service = useNotesService();
  return React.createElement(NotesContext.Provider, { value: service }, children);
}

export function useNotes() {
  const context = useContext(NotesContext);
  if (context) {
    return context;
  }
  return useNotesService();
}

export function useNote(id: string | null) {
  const [note, setNote] = useState<Note | null>(null);
  useEffect(() => {
    if (!id) {
      setNote(null);
      return;
    }
    const subscription = liveQuery(() => getLocalNote(id)).subscribe((n) => {
      setNote(n as Note | undefined || null);
    });
    return () => subscription.unsubscribe();
  }, [id]);
  return note;
}

