import type { Note } from "@/types/note";
import * as api from "@/lib/api";
import { db } from "./db";
import { processSyncQueue } from "./syncEngine";

/** Merge server notes into IndexedDB without resurrecting locally deleted tombstones. */
export async function mergeServerNotesIntoLocal(
  notes: Note[],
  opts: { purgeMissing?: boolean } = {},
) {
  const purgeMissing = opts.purgeMissing !== false;
  const pendingCreates = new Set(
    (await db.syncQueue.where("type").equals("CREATE_NOTE").toArray()).map((op) => op.entityId),
  );

  await db.transaction("rw", db.notes, async () => {
    for (const note of notes) {
      if (pendingCreates.has(note.id)) continue;

      const exists = await db.notes.get(note.id);
      if (exists?.isDeleted) continue;
      if (exists) {
        if (exists.syncStatus === "synced") {
          await db.notes.update(note.id, {
            ...note,
            title: note.title ?? null,
            tags: note.tags ?? [],
            syncStatus: "synced",
            isDeleted: false,
          } as any);
        }
        continue;
      }

      try {
        await db.notes.add({
          ...note,
          title: note.title ?? null,
          tags: note.tags ?? [],
          syncStatus: "synced",
          isDeleted: false,
        } as any);
      } catch (err) {
        // Race: another tab or sync just wrote this id — update instead of crashing.
        if (err instanceof Error && err.name === "ConstraintError") {
          await db.notes.update(note.id, {
            ...note,
            title: note.title ?? null,
            tags: note.tags ?? [],
            syncStatus: "synced",
            isDeleted: false,
          } as any);
        } else {
          throw err;
        }
      }
    }

    if (purgeMissing) {
      const serverIds = new Set(notes.map((n) => n.id));
      const allLocal = await db.notes.filter((n) => !n.isDeleted && n.syncStatus === "synced").toArray();
      for (const local of allLocal) {
        if (!serverIds.has(local.id) && !pendingCreates.has(local.id)) {
          await db.notes.delete(local.id);
        }
      }
    }
  });
}

const SEED_PAGE_SIZE = 100;

/** Push local changes first, then merge server state (avoids seed/sync races). */
export async function pullServerNotes() {
  await processSyncQueue();
  const notes: Note[] = [];
  let page = 1;
  let total = 0;
  let totalPages = 1;
  do {
    const data = await api.fetchNotes(page, SEED_PAGE_SIZE);
    const batch = data.notes ?? [];
    notes.push(...batch);
    total = data.pagination?.total ?? notes.length;
    totalPages = Math.max(1, data.pagination?.totalPages ?? 1);
    if (batch.length > 0) {
      await mergeServerNotesIntoLocal(batch, { purgeMissing: false });
    } else {
      break;
    }
    page += 1;
  } while (page <= totalPages);

  await mergeServerNotesIntoLocal(notes, { purgeMissing: true });
  return {
    notes,
    pagination: { page: 1, pageSize: notes.length, total, totalPages: 1 },
  };
}

export async function fetchNotes(page = 1, pageSize = 50): Promise<NotesResponse> {
  const url = `${API_BASE}/notes?page=${page}&pageSize=${pageSize}`;
  console.log('[API] Fetching notes:', url);
  const res = await fetch(url, fetchOpts);
  console.log('[API] Response status:', res.status);
  if (res.status === 401) {
    console.warn('[API] Unauthorized');
    return { notes: [], pagination: { page: 1, pageSize, total: 0, totalPages: 0 } };
  }
  await throwIfNotOk(res);
  const data = await res.json();
  console.log('[API] Response data:', data);
  return data;
}

export async function fetchNote(id: string): Promise<Note> {
  const res = await fetch(`${API_BASE}/notes/${encodeURIComponent(id)}`, fetchOpts);
  await throwIfNotOk(res);
  return res.json();
}

export async function createNote(body: { id?: string; content: string; title?: string | null; color?: string; tags?: string[]; pinned?: boolean; position?: number }) {
  return fetchWithTimeout(`${API_BASE}/notes`, {
    ...fetchOpts,
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  }).then(throwIfNotOk).then(r => r.json());
}

export async function updateNote(id: string, body: Partial<{ content: string; title: string | null; color: string; tags: string[]; pinned: boolean; position: number }>) {
  return fetchWithTimeout(`${API_BASE}/notes/${id}`, {
    ...fetchOpts,
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  }).then(throwIfNotOk).then(r => r.json());
}


