function noteResponse(
  row: NoteRow,
  content: string,
): Record<string, unknown> {
  let tags: string[] = [];
  try {
    tags = JSON.parse(row.tags) as string[];
  } catch {
    tags = [];
  }
  return {
    id: row.id,
    title: row.title ?? undefined,
    content,
    color: row.color,
    tags,
    pinned: Boolean(row.pinned),
    position: row.position,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

