      .bind(noteId, userId)
      .run();
  }

  const updated = await assertNoteOwned(env, userId, noteId);
  return json(env, request, {
    noteId,
    summary,
    ocrText: "",
    ocrErrors,
    mediaCount: mediaIds.length,
    appended: append,
    note: updated ? noteResponse(updated, content) : null,
  });
}

