import { Note, NoteColor } from '@/types/note';
import { Pin, MoreVertical } from 'lucide-react';
import { parseNoteContentToNodes } from '@/lib/note-media';
import { Badge } from "@/components/ui/badge";

interface NoteCardProps {
  note: Note;
  onClick: () => void;
  onTogglePin: () => void;
  onTagClick?: (tag: string) => void;
}

const colorClasses: Record<NoteColor, string> = {
  white: 'bg-note-default',
  yellow: 'bg-note-cream',
  green: 'bg-note-mint',
  blue: 'bg-note-sky',
  pink: 'bg-note-rose',
  purple: 'bg-note-lavender',
};

export function NoteCard({ note, onClick, onTogglePin, onTagClick }: NoteCardProps) {
  const raw = String(note.content ?? "");
  const hasMedia = /(?:mynotes|zenotes):media:/i.test(raw);
  const isLongContent = raw.length > 150;
  const longTextOnlyPreview = isLongContent && !hasMedia;

  return (
    <div
      className={`
        masonry-item group relative rounded-2xl cursor-pointer
        border border-border/40 hover:border-border/80
        transition-all duration-300 ease-out hover:-translate-y-1
        ${colorClasses[note.color]}
        shadow-note hover:shadow-note-hover
        animate-scale-in overflow-hidden
      `}
      onClick={onClick}
    >
      {/* Pin indicator */}
      {note.pinned && (
        <div className="absolute top-2 right-2 z-10 w-7 h-7 bg-gradient-to-br from-primary to-accent rounded-full flex items-center justify-center shadow-lg animate-pop">
          <Pin className="w-3.5 h-3.5 text-primary-foreground fill-current" />
        </div>
      )}

      <div className="p-4 pb-11">
        {note.title && (
          <h3 className="font-semibold text-foreground pr-6 text-[15px] leading-snug mb-2">
            {note.title}
          </h3>
        )}
        {raw.trim() ? (
        <div
          className={`
          text-sm text-foreground/75 leading-relaxed min-h-[1.1em] break-words
          ${hasMedia ? "max-h-[min(70vh,28rem)] overflow-y-auto" : ""}
          ${longTextOnlyPreview ? "max-h-[6.75rem] overflow-hidden" : ""}
        `}
        >
          {parseNoteContentToNodes(raw, note.id, "card")}
        </div>
        ) : (
          <p className="text-xs text-muted-foreground/50">无正文</p>
        )}

        {note.tags?.length > 0 && (
          <div className="mt-3 flex flex-wrap gap-2">
            {note.tags.slice(0, 4).map((t) => (
              <Badge
                key={t}
                variant="secondary"
                onClick={(e) => {
                  e.stopPropagation();
                  onTagClick?.(t);
                }}
                className="cursor-pointer"
              >
                {t}
              </Badge>
            ))}
          </div>
        )}
      </div>

      {/* Hover Actions */}
      <div className="
        absolute bottom-2 left-2 right-2 flex items-center gap-0.5
        opacity-0 group-hover:opacity-100 transition-opacity duration-300
      ">
        <button
          onClick={(e) => {
            e.stopPropagation();
            onTogglePin();
          }}
          className={`
            p-2 rounded-lg hover:bg-foreground/8 transition-all duration-200
            ${note.pinned ? 'text-primary' : 'text-muted-foreground'}
          `}
          title={note.pinned ? 'Unpin' : 'Pin'}
        >
          <Pin className={`w-4 h-4 ${note.pinned ? 'fill-current' : ''}`} />
        </button>
        <button
          onClick={(e) => e.stopPropagation()}
          className="p-2 rounded-lg text-muted-foreground hover:bg-foreground/8 transition-all duration-200 ml-auto"
        >
          <MoreVertical className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}

import type { ReactNode } from "react";
import { NoteEmbeddedImage } from "@/components/NoteEmbeddedImage";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

const API_BASE = import.meta.env.VITE_API_BASE || "/api";

/** 正文里插入的图片占位（与 Worker 约定一致）；旧数据可能仍为 `mynotes:media:`，解析时二者皆支持 */
export const NOTE_MEDIA_PREFIX = "zenotes:media:";

const NOTE_MEDIA_IN_BODY =
  /!\[([^\]]*)\]\((?:mynotes|zenotes):media:([0-9a-f-]{36})\)/gi;

export type ContentBlock =
  | { type: "text"; text: string }
  | { type: "image"; alt: string; mediaId: string };

const MEDIA_LINE_RE = NOTE_MEDIA_IN_BODY;

/**
 * 保证：首块不是孤立的图、末块不是孤立的图、相邻图片之间有可编辑文字。
 * 避免「整篇只有一张图」时没有任何 textarea。
 */
export function ensureEditableTextAroundImages(blocks: ContentBlock[]): ContentBlock[] {
  if (blocks.length === 0) {
    return [{ type: "text", text: "" }];
  }
  const out: ContentBlock[] = [];
  for (const cur of blocks) {
    if (cur.type === "image" && out.length > 0 && out[out.length - 1]!.type === "image") {
      out.push({ type: "text", text: "\n\n" });
    }
    out.push(cur);
  }
  let r = out;
  if (r[0]!.type === "image") {
    r = [{ type: "text", text: "" }, ...r];
  }
  if (r[r.length - 1]!.type === "image") {
    r = [...r, { type: "text", text: "" }];
  }
  return r;
}

/** 将正文拆成「文字 / 图片」交替块，用于编辑区按顺序渲染 */
export function parseContentToBlocks(content: string): ContentBlock[] {
  const blocks: ContentBlock[] = [];
  let last = 0;
  let m: RegExpExecArray | null;
  const re = new RegExp(MEDIA_LINE_RE.source, MEDIA_LINE_RE.flags);
  while ((m = re.exec(content)) !== null) {
    if (m.index > last) {
      blocks.push({ type: "text", text: content.slice(last, m.index) });
    }
    blocks.push({ type: "image", alt: (m[1] && m[1].trim()) || "image", mediaId: m[2]! });
    last = m.index + m[0].length;
  }
  if (last < content.length) {
    blocks.push({ type: "text", text: content.slice(last) });
  }
  if (blocks.length === 0) {
    blocks.push({ type: "text", text: content });
  }
  return ensureEditableTextAroundImages(blocks);
}

export function blocksToContent(blocks: ContentBlock[]): string {
  return blocks
    .map((b) =>
      b.type === "text" ? b.text : `![${b.alt}](${NOTE_MEDIA_PREFIX}${b.mediaId})`,
    )
    .join("");
}

/** 把正文里误贴在文字块中的图片 Markdown 等重新拆成图文块 */
export function normalizeContentBlocks(blocks: ContentBlock[]): ContentBlock[] {
  return parseContentToBlocks(blocksToContent(blocks));
}

